import { test, expect } from '@playwright/test';

test.describe('Form Submission with Future Date in Past-Date Field', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display error when future date is entered in past-date field', async ({ page }) => {
    // Locate and fill future date in past-date field using getByLabel
    const pastDateInput = page.getByLabel('Past Date');
    await pastDateInput.fill('2023-12-31');

    // Locate and fill other required fields using getByLabel
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('john.doe@example.com');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify error message appears using getByRole
    const errorMessage = page.getByText('Date cannot be in the future');
    await expect(errorMessage).toBeVisible();

    // Verify form is still visible
    const formContainer = page.getByRole('region', { name: 'Form' });
    await expect(formContainer).toBeVisible();

    // Verify form fields are still editable
    await expect(pastDateInput).toBeEditable();
    await expect(nameInput).toBeEditable();
    await expect(emailInput).toBeEditable();
  });

  test('should successfully submit form when past date is entered in past-date field', async ({ page }) => {
    // Locate and fill future date in past-date field using getByLabel
    const pastDateInput = page.getByLabel('Past Date');
    await pastDateInput.fill('2023-01-01');

    // Locate and fill other required fields using getByLabel
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('Jane Smith');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('jane.smith@example.com');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify success message appears using getByText
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify form is still visible
    const formContainer = page.getByRole('region', { name: 'Form' });
    await expect(formContainer).toBeVisible();

    // Verify form fields are no longer editable
    await expect(pastDateInput).not.toBeEditable();
    await expect(nameInput).not.toBeEditable();
    await expect(emailInput).not.toBeEditable();
  });
});
